My solution for the Put route:

router.put("/:id", (req, res) => {
    const user = users.find((u) => u.id === +req.params.id)
    if (user) {
        for (const key in req.body) user[key] = req.body[key]
        res.send(user)
    } else {
        res.status(400)
        res.send("Not Found Yo!")
    }
})

